import * as z from 'zod';

/**
 * The private overlay (docs/CLUSTERING.md §4.1, phase C1).
 *
 * The control plane allocates one /32 per managed node and computes a hub-plus-LAN peer graph.
 * Only public keys travel: the private key is generated by the root helper on the node and never
 * leaves it. Bring-your-own networks and host-provisioned WireGuard stay `external` and receive
 * no managed peer list.
 */

export const nodeNetworkModes = ['yoal', 'external', 'edge'] as const;
export type NodeNetworkMode = (typeof nodeNetworkModes)[number];
export const nodeNetworkModeSchema = z.enum(nodeNetworkModes);

/** WireGuard interface defaults; a path probe may lower the MTU to 1280. */
export const DEFAULT_OVERLAY_CIDR = '10.47.0.0/22';
export const DEFAULT_WG_PORT = 51820;
export const DEFAULT_WG_MTU = 1420;
export const WG_KEEPALIVE_SECONDS = 25;

/**
 * How managed nodes reach each other (docs/CLUSTERING.md §4.7, D240). `hub` is §4.1: spokes peer with
 * the hubs and with nodes on their own private network, and every other pair is relayed. `mesh`
 * additionally tries every other pair directly, punching through NAT on the endpoints the hubs
 * observe, and keeps the hub as the relay for a pair whose direct path never answers.
 */
export const overlayModes = ['hub', 'mesh'] as const;
export type OverlayMode = (typeof overlayModes)[number];

/** Names every overlay node gets in mesh mode: `<node>.yoal.internal`. */
export const OVERLAY_NAME_SUFFIX = 'yoal.internal';

/** A WireGuard public key is 32 bytes, base64 with the trailing `=`. */
export const wireguardPublicKeySchema = z
	.string()
	.trim()
	.regex(/^[A-Za-z0-9+/]{43}=$/, 'Use a base64 WireGuard public key.');

export const overlayAddressSchema = z
	.string()
	.trim()
	.regex(/^(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}$/, 'Use an IPv4 address.');

export const wireguardPeerSchema = z.object({
	/** The node this peer represents; a hub peer carries every node routed through it. */
	nodeId: z.string().min(1).max(100),
	publicKey: wireguardPublicKeySchema,
	/** `host:port` or null for a peer that dials out and is learned from its handshake. */
	endpoint: z.string().max(253).nullable().default(null),
	/**
	 * Every /32 this peer is allowed to route (cryptokey routing), plus the /24 machine subnet of a
	 * node that runs multi-node Kubernetes machines (docs/KUBERNETES.md §10), sent only to nodes
	 * whose agent advertises `wg-subnets`. Empty for a mesh pair still being probed (§4.7): the
	 * handshake runs on keepalives while the hub keeps carrying the traffic, and only nodes that
	 * advertise `wg-mesh` ever receive an empty list.
	 */
	allowedIps: z.array(z.string().regex(/^(?:\d{1,3}\.){3}\d{1,3}\/(?:32|24)$/)).max(128),
	persistentKeepalive: z.number().int().min(0).max(65_535).default(WG_KEEPALIVE_SECONDS),
});
export type WireguardPeer = z.infer<typeof wireguardPeerSchema>;

export const overlayHostSchema = z.object({
	name: z.string().regex(/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.yoal\.internal$/),
	address: overlayAddressSchema,
});
export type OverlayHost = z.infer<typeof overlayHostSchema>;

export const wireguardStateSchema = z.object({
	mode: nodeNetworkModeSchema,
	address: overlayAddressSchema.nullable().default(null),
	cidr: z.string().max(32).nullable().default(null),
	mtu: z.number().int().min(1280).max(1420).default(DEFAULT_WG_MTU),
	listenPort: z.number().int().min(1).max(65_535).default(DEFAULT_WG_PORT),
	peers: z.array(wireguardPeerSchema).max(64).default([]),
	/** Extra prefixes routed into the interface (the Kubernetes machine supernet). */
	routes: z.array(z.string().regex(/^(?:\d{1,3}\.){3}\d{1,3}\/\d{1,2}$/)).max(8).default([]),
	/** This node's own machine subnet, which its `yoal-k8s` network uses (K6). */
	machineSubnet: z.string().regex(/^(?:\d{1,3}\.){3}0\/24$/).nullable().default(null),
	/**
	 * Overlay names for `/etc/hosts` (mesh mode, §4.7): every managed node as `<name>.yoal.internal`.
	 * Sent only in mesh mode; absent or empty removes the helper's block, and nothing else in the file.
	 */
	hosts: z.array(overlayHostSchema).max(64).optional(),
});
export type WireguardState = z.infer<typeof wireguardStateSchema>;

/** Added to the join request by the managed installer; absent means a BYO/external node. */
export const nodeJoinNetworkSchema = z.object({
	networkMode: z.enum(['yoal', 'external']).default('external'),
	wireguardPublicKey: wireguardPublicKeySchema.optional(),
});
export type NodeJoinNetwork = z.infer<typeof nodeJoinNetworkSchema>;

/** The helper's `wg show <if> dump`, reduced to public data. */
export const wireguardPeerStatusSchema = z.object({
	publicKey: wireguardPublicKeySchema,
	endpoint: z.string().max(253).nullable().default(null),
	latestHandshakeAt: z.string().max(40).nullable().default(null),
	rxBytes: z.number().int().nonnegative().default(0),
	txBytes: z.number().int().nonnegative().default(0),
});
export type WireguardPeerStatus = z.infer<typeof wireguardPeerStatusSchema>;

export const wireguardStatusSchema = z.object({
	interface: z.string().min(1).max(32),
	peers: z.array(wireguardPeerStatusSchema).max(64).default([]),
});
export type WireguardStatus = z.infer<typeof wireguardStatusSchema>;

/** Kubernetes machines on multi-node clusters get routed addresses from here (docs/KUBERNETES.md §10). */
export const DEFAULT_K8S_MACHINE_CIDR = '10.48.0.0/16';
/** The agent capability that says its helper accepts /24 machine subnets in WireGuard peers. */
export const WG_SUBNETS_CAPABILITY = 'wg-subnets';
/**
 * The helper accepts a peer with no allowed IPs (a mesh probe), applies peers with `wg syncconf` so
 * live sessions and roamed endpoints survive a re-apply, and writes the overlay names (§4.7).
 */
export const WG_MESH_CAPABILITY = 'wg-mesh';

/**
 * A node's machine subnet: `10.48.<n>.0/24`, where n is the node's host number in the overlay
 * (`10.47.1.5` → 5, `10.47.2.5` → 261 mod 256). Collides only beyond 255 overlay nodes.
 */
export function machineSubnetFor(privateAddress: string | null, supernet = DEFAULT_K8S_MACHINE_CIDR): string | null {
	if (!privateAddress) return null;
	const parts = privateAddress.split('.').map(Number);
	if (parts.length !== 4 || parts.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) return null;
	const base = supernet.split('/')[0]!.split('.').map(Number);
	const index = ((parts[2]! - 1) * 256 + parts[3]!) % 256;
	if (index <= 0) return null;
	return `${base[0]}.${base[1]}.${index}.0/24`;
}
